function transactionsTable(list,compact=false){return `<div class="table-wrap"><table class="tx-table${compact?' compact':''}"><thead><tr><th>תנועה</th><th>קטגוריה</th>${compact?'':'<th>חשבון</th><th>תאריך</th>'}<th>סכום</th>${compact?'':'<th aria-label="פעולות"></th>'}</tr></thead><tbody>${list.map(t=>`<tr><td><div class="transaction-name"><span class="transaction-icon ${t.type==='income'?'green':''}">${icon(t.type==='income'?'ArrowDownLeft':'ArrowUpLeft',17)}</span><div><b>${e(t.description||t.category)}</b><small>${e(compact?dateLabel(t.date):[t.subcategory,...t.tags||[],t.recurring?'תנועה חודשית':''].filter(Boolean).join(' · '))}</small></div></div></td><td><span class="category-pill">${e(t.category)}</span></td>${compact?'':`<td>${e(data.accounts.find(a=>a.id===t.accountId)?.name||'—')}</td><td class="muted">${dateLabel(t.date)}</td>`}<td><b dir="ltr" class="${t.type==='income'?'positive':''}">${t.type==='income'?'+':'−'}${money(t.amount,t.currency||'ILS')}</b></td>${compact?'':`<td><div class="table-actions">${ib('Pencil','עריכת התנועה','edit:transaction:'+t.id)}${ib('Trash2','מחיקת התנועה','remove:transaction:'+t.id)}</div></td>`}</tr>`).join('')}</tbody></table>${list.length?'':compact?empty('עוד אין תנועות החודש','כל הוצאה או הכנסה שתוסיף תופיע כאן.',btn('הוספת תנועה','quick-add','Plus','primary')):empty('לא נמצאו תנועות','אפשר לשנות מסננים או להוסיף תנועה חדשה.')}</div>`;}
